4	import org.springframework.context.annotation.Configuration;
5	import org.springframework.core.io.Resource;
6	import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
7	import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
8	import org.springframework.web.servlet.resource.PathResourceResolver;
9	
10	/**
11	 * Serve the SPA from static/ with a deep-link fallback: an unknown, non-API path returns
12	 * index.html so a browser refresh on a client route works. OfficeFloor REST routes and Spring
13	 * endpoints are matched first; only unmatched, non-{@code api/} paths fall through to the SPA.
14	 * TODO: confirm the API path prefix used by the OfficeFloor routes ("api/" assumed here).
15	 */
16	@Configuration
17	public class SpaConfig implements WebMvcConfigurer {
18	
19	    @Override
20	    public void addResourceHandlers(ResourceHandlerRegistry registry) {
21	        registry.addResourceHandler("/**")
22	                .addResourceLocations("classpath:/static/")
23	                .resourceChain(true)
24	                .addResolver(new PathResourceResolver() {
